"""Compares the parse speed of cimai, the MajSimai C# parser and MajSimai through the C++ wrapper generated by
tools/MajSimai.CppGen.

Usage:
    python tools/benchmark-native.py --cimai <cimai repository> --samples <sample folder> [options]

The script
  1. makes a MajSimai C++ package with tools/build-cpp-package.py (or uses --package),
  2. builds tools/NativeBenchmark with CMake: cimai from its sources and a program for each native parser,
  3. packs every maidata.txt of the sample folder into one corpus, which every benchmark reads into memory,
  4. runs each native parser over the whole corpus (warm-up runs, then measured runs) in its own process,
  5. runs the corpus benchmarks of tools/MajSimai.ManagedBenchmark with BenchmarkDotNet on net10.0 (the framework of
     the package), with the same warm-up and measured runs (--strategy Monitoring),
  6. prints a table and writes the report to <build folder>/report.json and report.md; BenchmarkDotNet writes its own
     reports to <build folder>/bdn/results.

Runs (--parsers):
  cimai                   cimai_parse + cimai_file_release
  majsimai-cs             SimaiParser.Parse on the .NET runtime (JIT), as the native entry point calls it
  majsimai-cs-native-abi  MajSimai_ParseWithTolerance + MajSimai_Free called in-process on the .NET runtime (JIT):
                          the parse and the copy into native memory, without the C++ wrapper
  majsimai-cpp-view       SimaiParser::ParseAsView: parse with native AOT, convert to native memory, read it through views
  majsimai-cpp-model      SimaiParser::Parse: as view, then copy everything into std::string / std::vector

The native programs time every file, so their rows have per-file percentiles; BenchmarkDotNet times whole runs over
the corpus, so the C# rows have none, but they have the memory allocated per run. The parsers do not produce the same
data and do not report errors the same way (cimai has no error result), so the note counts in the report are
checksums of each parser, not a correctness comparison.

It needs Python 3.8+ and the .NET 10 SDK; the cimai and C++ runs also need CMake 3.21+, a C/C++ toolchain and what
tools/build-cpp-package.py needs. On Windows CMake is also looked up in the Visual Studio installations when it is not
on the path.
"""
import argparse
import json
import os
import platform
import shutil
import statistics
import struct
import subprocess
import sys
from pathlib import Path

REPOSITORY = Path(__file__).resolve().parent.parent
BENCHMARK_SOURCE = REPOSITORY / "tools" / "NativeBenchmark"
PACKAGE_SCRIPT = REPOSITORY / "tools" / "build-cpp-package.py"
MANAGED_PROJECT = REPOSITORY / "tools" / "MajSimai.ManagedBenchmark" / "MajSimai.ManagedBenchmark.csproj"
MANAGED_FRAMEWORK = "net10.0"
MANAGED_CLASS = "MajSimai.ManagedBenchmark.CorpusParseBenchmarks"
CORPUS_VARIABLE = "MAJSIMAI_BENCHMARK_CORPUS"
CONFIGURATION = "Release"
# A run: its name (--parsers), the parser and mode shown in the report, whether it is a native program, and the native
# program or the method of CorpusParseBenchmarks that measures it.
RUNS = [
    {"name": "cimai", "parser": "cimai", "mode": "parse", "native": True, "target": "CimaiBenchmark"},
    {"name": "majsimai-cs", "parser": "majsimai-cs", "mode": "parse", "native": False, "target": "Parse"},
    {"name": "majsimai-cs-native-abi", "parser": "majsimai-cs", "mode": "native-abi", "native": False, "target": "ParseToNative"},
    {"name": "majsimai-cpp-view", "parser": "majsimai-cpp", "mode": "view", "native": True, "target": "MajSimaiBenchmark"},
    {"name": "majsimai-cpp-model", "parser": "majsimai-cpp", "mode": "model", "native": True, "target": "MajSimaiBenchmark"},
]
RUN_NAMES = [entry["name"] for entry in RUNS]


def fail(message):
    print(f"error: {message}", file=sys.stderr)
    sys.exit(1)


def run(command, **kwargs):
    print("> " + " ".join(str(part) for part in command), flush=True)
    result = subprocess.run([str(part) for part in command], **kwargs)
    if result.returncode != 0:
        fail(f"the command above failed with exit code {result.returncode}")


def host_runtime_identifier():
    """Gets the .NET runtime identifier of this computer, such as win-x64; the same rule as build-cpp-package.py."""
    systems = {"Linux": "linux", "Darwin": "osx", "Windows": "win"}
    architectures = {"x86_64": "x64", "amd64": "x64", "aarch64": "arm64", "arm64": "arm64"}
    system = systems.get(platform.system())
    architecture = architectures.get(platform.machine().lower())
    if system is None or architecture is None:
        fail(f"cannot tell the runtime identifier of {platform.system()} {platform.machine()}; pass --package")
    return f"{system}-{architecture}"


def find_cmake(explicit):
    """Finds cmake: --cmake, the path, or on Windows the CMake that comes with Visual Studio."""
    if explicit:
        return explicit
    found = shutil.which("cmake")
    if found:
        return found
    if platform.system() == "Windows":
        vswhere = Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")) / "Microsoft Visual Studio" / "Installer" / "vswhere.exe"
        if vswhere.is_file():
            result = subprocess.run([str(vswhere), "-all", "-products", "*", "-property", "installationPath"],
                                    capture_output=True, text=True)
            for installation in result.stdout.splitlines():
                candidate = Path(installation.strip()) / "Common7" / "IDE" / "CommonExtensions" / "Microsoft" / "CMake" / "CMake" / "bin" / "cmake.exe"
                if candidate.is_file():
                    return str(candidate)
    fail("CMake was not found; install it, put it on the path or pass --cmake")


def prepare_package(arguments):
    """Returns the MajSimai C++ package to benchmark, building it with build-cpp-package.py when needed."""
    if arguments.package:
        package = Path(arguments.package).resolve()
        if not (package / "MajSimaiNative.json").is_file():
            fail(f"'{package}' is not a package made by tools/build-cpp-package.py")
        return package
    package = REPOSITORY / "artifacts" / "cpp" / f"{host_runtime_identifier()}-{arguments.kind}"
    if arguments.rebuild_package or not (package / "MajSimaiNative.json").is_file():
        run([sys.executable, PACKAGE_SCRIPT, "--kind", arguments.kind, "--output", package])
    else:
        print(f"Using the MajSimai package in '{package}' (pass --rebuild-package to build it again).")
    return package


def build_native(arguments, cmake, package, build):
    """Configures and builds tools/NativeBenchmark and returns the folder of the programs."""
    run([cmake, "-S", BENCHMARK_SOURCE, "-B", build,
         f"-DCIMAI_DIR={Path(arguments.cimai).resolve().as_posix()}",
         f"-DMAJSIMAI_PACKAGE_DIR={package.as_posix()}",
         f"-DBENCHMARK_LIBRARY_TYPE={arguments.kind.upper()}",
         f"-DCMAKE_BUILD_TYPE={CONFIGURATION}"])
    run([cmake, "--build", build, "--config", CONFIGURATION, "--parallel"])
    return build / "bin" / CONFIGURATION


def find_program(folder, name):
    for candidate in (folder / name, folder / f"{name}.exe"):
        if candidate.is_file():
            return candidate
    fail(f"the benchmark program {name} was not built in '{folder}'")


def write_corpus(samples, limit, corpus):
    """Packs the sample files into the corpus format of BenchmarkCommon.h and returns their paths and sizes."""
    files = sorted(samples.rglob("maidata.txt"))
    if limit:
        files = files[:limit]
    if not files:
        fail(f"'{samples}' has no maidata.txt")
    entries = []
    with open(corpus, "wb") as output:
        output.write(struct.pack("<I", len(files)))
        for file in files:
            content = file.read_bytes()
            output.write(struct.pack("<I", len(content)))
            output.write(content)
            entries.append({"path": file.relative_to(samples).as_posix(), "bytes": len(content)})
    return entries


def run_native(program, mode, corpus, result, arguments):
    """Runs one native benchmark program over the corpus and returns its result."""
    command = [program, result, arguments.warmup, arguments.iterations, mode]
    print("> " + " ".join(str(part) for part in command) + f" < {corpus.name}", flush=True)
    with open(corpus, "rb") as input_file:
        # MajSimai logs warnings of malformed charts to standard output; they are not part of the measurement.
        completed = subprocess.run([str(part) for part in command], stdin=input_file, stdout=subprocess.DEVNULL)
    if completed.returncode != 0:
        print(f"warning: {program.name} {mode} failed with exit code {completed.returncode:#x}; it is left out of the report",
              file=sys.stderr)
        return None
    return json.loads(result.read_text(encoding="utf-8"))


def run_managed(methods, corpus, artifacts, arguments):
    """Runs methods of CorpusParseBenchmarks with BenchmarkDotNet and returns their reports by method name."""
    results = artifacts / "results"
    shutil.rmtree(results, ignore_errors=True)
    command = [arguments.dotnet, "run", "-c", CONFIGURATION, "--project", MANAGED_PROJECT, "-f", MANAGED_FRAMEWORK, "--",
               "--filter", *[f"{MANAGED_CLASS}.{method}" for method in methods],
               "--strategy", "Monitoring", "--warmupCount", arguments.warmup, "--iterationCount", arguments.iterations,
               "--exporters", "json", "--artifacts", artifacts]
    print("> " + " ".join(str(part) for part in command), flush=True)
    environment = dict(os.environ)
    environment[CORPUS_VARIABLE] = str(corpus)
    completed = subprocess.run([str(part) for part in command], env=environment)
    reports = sorted(results.glob("*CorpusParseBenchmarks-report-full*.json")) if results.is_dir() else []
    if completed.returncode != 0 or not reports:
        print(f"warning: BenchmarkDotNet failed with exit code {completed.returncode:#x}; the C# runs are left out of the report",
              file=sys.stderr)
        return {}
    report = json.loads(reports[0].read_text(encoding="utf-8"))
    return {benchmark["Method"]: benchmark for benchmark in report["Benchmarks"]}


def percentile(values, fraction):
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, int(round(fraction * (len(ordered) - 1))))]


def largest_index(entries):
    return max(range(len(entries)), key=lambda index: entries[index]["bytes"])


def summarize_native(entry, raw, entries):
    """Turns the result of a native program into the numbers of the report."""
    runs_ms = [ns / 1e6 for ns in raw["runNs"]]
    file_us = [ns / 1e3 for ns in raw["fileMinNs"]]
    median_ms = statistics.median(runs_ms)
    largest = largest_index(entries)
    return {
        "name": entry["name"],
        "parser": entry["parser"],
        "mode": entry["mode"],
        "measuredBy": "tools/NativeBenchmark",
        "files": raw["files"],
        "bytes": raw["bytes"],
        "failures": raw["failures"],
        "notes": raw["notes"],
        "runsMs": runs_ms,
        "medianMs": median_ms,
        "minMs": min(runs_ms),
        "stdevMs": statistics.stdev(runs_ms) if len(runs_ms) > 1 else 0.0,
        "allocatedMiB": None,
        "mibPerSecond": raw["bytes"] / (1024 * 1024) / (median_ms / 1000),
        "filesPerSecond": raw["files"] / (median_ms / 1000),
        "fileP50Us": percentile(file_us, 0.50),
        "fileP90Us": percentile(file_us, 0.90),
        "fileP99Us": percentile(file_us, 0.99),
        "fileMaxUs": max(file_us),
        "slowestFile": entries[max(range(len(file_us)), key=file_us.__getitem__)]["path"],
        "largestFile": entries[largest]["path"],
        "largestFileUs": file_us[largest],
    }


def summarize_managed(entry, benchmark, entries):
    """Turns the BenchmarkDotNet report of a corpus benchmark into the numbers of the report."""
    statistics_ns = benchmark["Statistics"]
    memory = benchmark.get("Memory") or {}
    total = sum(item["bytes"] for item in entries)
    median_ms = statistics_ns["Median"] / 1e6
    allocated = memory.get("BytesAllocatedPerOperation")
    return {
        "name": entry["name"],
        "parser": entry["parser"],
        "mode": entry["mode"],
        "measuredBy": "BenchmarkDotNet",
        "files": len(entries),
        "bytes": total,
        "failures": None,
        "notes": None,
        "runsMs": [ns / 1e6 for ns in statistics_ns.get("OriginalValues", [])],
        "medianMs": median_ms,
        "minMs": statistics_ns["Min"] / 1e6,
        "stdevMs": statistics_ns["StandardDeviation"] / 1e6,
        "allocatedMiB": allocated / (1024 * 1024) if allocated is not None else None,
        "mibPerSecond": total / (1024 * 1024) / (median_ms / 1000),
        "filesPerSecond": len(entries) / (median_ms / 1000),
        "fileP50Us": None,
        "fileP90Us": None,
        "fileP99Us": None,
        "fileMaxUs": None,
        "slowestFile": None,
        "largestFile": entries[largest_index(entries)]["path"],
        "largestFileUs": None,
    }


def number(value, digits=1):
    """Formats a number of the report, or '-' when the benchmark does not measure it."""
    return "-" if value is None else f"{value:.{digits}f}"


def format_report(summaries, entries, arguments, artifacts):
    """Formats the summaries as a Markdown table."""
    baseline = next((summary for summary in summaries if summary["parser"] == "cimai"), None)
    total = sum(entry["bytes"] for entry in entries)
    lines = [
        f"Files: {len(entries)}, {total / 1024 / 1024:.1f} MiB; {arguments.warmup} warm-up and {arguments.iterations} measured runs; "
        f"libraries: {arguments.kind}",
        "",
        "| Parser | Mode | Median (ms) | Min (ms) | Stdev (ms) | MiB/s | Files/s | Alloc/run (MiB) | p50 (us) | p99 (us) | Max (us) | "
        "Largest file (us) | vs cimai | Failures | Notes |",
        "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for summary in summaries:
        ratio = f"{summary['medianMs'] / baseline['medianMs']:.2f}x" if baseline else "-"
        failures = "-" if summary["failures"] is None else summary["failures"]
        notes = "-" if summary["notes"] is None else summary["notes"]
        lines.append(
            f"| {summary['parser']} | {summary['mode']} | {number(summary['medianMs'])} | {number(summary['minMs'])} | "
            f"{number(summary['stdevMs'])} | {number(summary['mibPerSecond'])} | {number(summary['filesPerSecond'], 0)} | "
            f"{number(summary['allocatedMiB'])} | {number(summary['fileP50Us'])} | {number(summary['fileP99Us'])} | "
            f"{number(summary['fileMaxUs'])} | {number(summary['largestFileUs'])} | {ratio} | {failures} | {notes} |")
    lines += ["", f"Largest file: {entries[largest_index(entries)]['path']}"]
    lines += [f"Slowest file for {summary['parser']} {summary['mode']}: {summary['slowestFile']}"
              for summary in summaries if summary["slowestFile"] is not None]
    lines += ["", "\"vs cimai\" is the median time divided by the median time of cimai: below 1 is faster than cimai.",
              "Native rows: tools/NativeBenchmark times every run and every file; per-file times are the fastest of the measured runs.",
              f"majsimai-cs rows: BenchmarkDotNet times every run (--strategy Monitoring) and the memory allocated per run; "
              f"its reports are in '{artifacts / 'results'}'.",
              "Note counts are per-parser checksums, not a correctness check."]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="Compares the parse speed of cimai, the MajSimai C# parser and the MajSimai C++ wrapper.")
    parser.add_argument("--cimai", default=os.environ.get("CIMAI_DIR"), help="the cimai repository (default: $CIMAI_DIR)")
    parser.add_argument("--samples", default=os.environ.get("MAJSIMAI_SAMPLES_DIR"),
                        help="the folder searched for maidata.txt (default: $MAJSIMAI_SAMPLES_DIR)")
    parser.add_argument("--kind", choices=["shared", "static"], default="shared",
                        help="link both native parsers as shared or static libraries (default: shared)")
    parser.add_argument("--package", help="an existing MajSimai C++ package; by default artifacts/cpp/<rid>-<kind> is used or built")
    parser.add_argument("--rebuild-package", action="store_true", help="build the MajSimai package even if it exists")
    parser.add_argument("--build", help="the build and report folder (default: artifacts/benchmark/<kind>)")
    parser.add_argument("--cmake", help="the cmake command (default: found on the path or in Visual Studio)")
    parser.add_argument("--dotnet", default="dotnet", help="the dotnet command for the C# benchmarks (default: dotnet)")
    parser.add_argument("--parsers", default=",".join(RUN_NAMES),
                        help=f"the runs, separated by commas (default: all): {', '.join(RUN_NAMES)}")
    parser.add_argument("--iterations", type=int, default=10, help="measured runs over the corpus (default: 10)")
    parser.add_argument("--warmup", type=int, default=2, help="warm-up runs over the corpus (default: 2)")
    parser.add_argument("--limit", type=int, default=0, help="use only the first N sample files, for a quick run")
    arguments = parser.parse_args()

    selected = [name.strip() for name in arguments.parsers.split(",") if name.strip()]
    unknown = [name for name in selected if name not in RUN_NAMES]
    if unknown or not selected:
        fail(f"--parsers takes {', '.join(RUN_NAMES)}; unknown: {', '.join(unknown) or '(none given)'}")
    runs = [entry for entry in RUNS if entry["name"] in selected]
    native_runs = [entry for entry in runs if entry["native"]]
    managed_runs = [entry for entry in runs if not entry["native"]]
    if native_runs and (not arguments.cimai or not (Path(arguments.cimai) / "include" / "cimai" / "cimai.h").is_file()):
        fail("--cimai (or CIMAI_DIR) must name the cimai repository")
    if not arguments.samples or not Path(arguments.samples).is_dir():
        fail("--samples (or MAJSIMAI_SAMPLES_DIR) must name the sample folder")
    if arguments.iterations < 1 or arguments.warmup < 0:
        fail("--iterations must be 1 or more and --warmup 0 or more")

    build = Path(arguments.build).resolve() if arguments.build else REPOSITORY / "artifacts" / "benchmark" / arguments.kind
    build.mkdir(parents=True, exist_ok=True)
    artifacts = build / "bdn"
    native_programs = None
    if native_runs:
        cmake = find_cmake(arguments.cmake)
        package = prepare_package(arguments)
        native_programs = build_native(arguments, cmake, package, build)
    corpus = build / "corpus.bin"
    entries = write_corpus(Path(arguments.samples).resolve(), arguments.limit, corpus)

    summaries_by_name = {}
    for entry in native_runs:
        raw = run_native(find_program(native_programs, entry["target"]), entry["mode"], corpus, build / f"result-{entry['name']}.json", arguments)
        if raw is not None:
            summaries_by_name[entry["name"]] = summarize_native(entry, raw, entries)
    if managed_runs:
        benchmarks = run_managed([entry["target"] for entry in managed_runs], corpus, artifacts, arguments)
        for entry in managed_runs:
            if entry["target"] in benchmarks:
                summaries_by_name[entry["name"]] = summarize_managed(entry, benchmarks[entry["target"]], entries)
    summaries = [summaries_by_name[entry["name"]] for entry in runs if entry["name"] in summaries_by_name]
    if not summaries:
        fail("no benchmark finished")

    report = format_report(summaries, entries, arguments, artifacts)
    (build / "report.md").write_text(report + "\n", encoding="utf-8")
    (build / "report.json").write_text(json.dumps({"kind": arguments.kind, "warmup": arguments.warmup,
                                                    "iterations": arguments.iterations, "results": summaries}, indent=2) + "\n",
                                       encoding="utf-8")
    print()
    print(report)
    print(f"\nThe report is in '{build / 'report.md'}' and '{build / 'report.json'}'.")


if __name__ == "__main__":
    main()
